    assert sum_squares([-1, -2, -3, -4]) == 1 - 2 - 3 + 16

def test_sum_squares_floats():
    # index 0 -> 0.25, index 3 -> 0.25, index 4 -> 0.125
    assert sum_squares([0.5, 0.5, 0.5, 0.5, 0.5]) == pytest.approx(1.625)

def test_sum_squares_longer_list():
