    lst = list(range(1, 18))
    expected = sum(lst)
    for i in (0, 3, 6, 9, 12):
        expected += lst[i]**2 - lst[i]
    for i in (4, 8, 16):
        expected += lst[i]**3 - lst[i]
    assert sum_squares(lst) == expected

def test_sum_squares_zeros():
    assert sum_squares([0, 0, 0, 0, 0]) == 0
